import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/marketing/waitlist/conversion
 *
 * Returns conversion stats for the current studio's waitlist.
 * Gated behind marketing_basic (Studio+).
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const studioId = authUser.studioId

    const now = new Date()
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString()
    const sixtyDaysAgo = new Date(now.getTime() - 60 * 24 * 60 * 60 * 1000).toISOString()

    // Current 30d window
    const [joinedRes, convertedRes, priorJoinedRes, priorConvertedRes] = await Promise.all([
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', thirtyDaysAgo),
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('status', 'booked')
        .gte('created_at', thirtyDaysAgo),
      // Prior 30d window (30-60 days ago)
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('created_at', sixtyDaysAgo)
        .lt('created_at', thirtyDaysAgo),
      supabase
        .from('waitlist_entries')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('status', 'booked')
        .gte('created_at', sixtyDaysAgo)
        .lt('created_at', thirtyDaysAgo),
    ])

    const joined30d = joinedRes.count ?? 0
    const converted30d = convertedRes.count ?? 0
    const priorJoined = priorJoinedRes.count ?? 0
    const priorConverted = priorConvertedRes.count ?? 0

    const conversion_rate = joined30d > 0 ? (converted30d / joined30d) * 100 : 0
    const prior_period_rate = priorJoined > 0 ? (priorConverted / priorJoined) * 100 : 0
    const delta_pct = prior_period_rate > 0
      ? ((conversion_rate - prior_period_rate) / prior_period_rate) * 100
      : null

    return NextResponse.json({
      data: {
        joined_30d: joined30d,
        converted_30d: converted30d,
        conversion_rate: Math.round(conversion_rate * 10) / 10,
        prior_period_rate: Math.round(prior_period_rate * 10) / 10,
        delta_pct: delta_pct !== null ? Math.round(delta_pct * 10) / 10 : null,
      },
    })
  } catch (err) {
    logger.error({ err }, 'waitlist conversion stats failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'

/**
 * GET  /api/marketing/waitlist/auto-promote-rules
 * PATCH /api/marketing/waitlist/auto-promote-rules
 *
 * Reads/upserts the studio's auto-promote rules for waitlist entries.
 * The marketing_waitlist_rules table is studio-scoped (one row per studio).
 *
 * Gated: owner/admin only, marketing_basic.
 */

const RulesSchema = z.object({
  auto_promote_on_cancel: z.boolean(),
  auto_promote_window_minutes: z.number().int().min(0).max(1440).default(5),
  min_lead_time_hours: z.number().int().min(0).max(168).default(24),
  notify_via: z.array(z.enum(['email', 'sms'])).min(1),
  template_subject: z.string().min(1).max(200),
  template_body: z.string().min(1).max(2000),
})

const DEFAULT_RULES = {
  auto_promote_on_cancel: false,
  auto_promote_window_minutes: 5,
  min_lead_time_hours: 24,
  notify_via: ['email'] as string[],
  template_subject: 'A spot just opened',
  template_body: 'A slot just opened: {{slot}}. Reply YES to claim it — this offer expires in 24 hours.',
}

export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('marketing_waitlist_rules')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist rules fetch failed')
      return NextResponse.json({ error: 'Failed to fetch rules' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? { ...DEFAULT_RULES, studio_id: authUser.studioId } })
  } catch (err) {
    logger.error({ err }, 'waitlist rules GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = RulesSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('marketing_waitlist_rules')
      .upsert(
        {
          studio_id: authUser.studioId,
          ...parsed.data,
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'studio_id' },
      )
      .select('*')
      .single()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist rules upsert failed')
      return NextResponse.json({ error: 'Failed to save rules' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.id,
      'waitlist_auto_promote_rules.upsert',
      { type: 'marketing_waitlist_rules', id: authUser.studioId },
      { auto_promote_on_cancel: parsed.data.auto_promote_on_cancel },
      authUser.studioId,
    )

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'waitlist rules PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

/**
 * GET /api/marketing/waitlist/list
 *
 * Returns waitlist_entries for the current studio with optional filters.
 * Joined with client, artist, service data.
 *
 * Query params:
 *   artist_id  — filter by artist
 *   service_id — filter by service
 *   event_id   — filter by flash_event (note: waitlist_entries doesn't yet have
 *               a flash_event_id column — returns empty if provided; TODO: M6 migration)
 *   status     — filter by status
 *   page       — 1-based page number (default 1)
 *   per_page   — items per page (default 50, max 100)
 */
export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await apiRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const { searchParams } = new URL(request.url)
  const artistId = searchParams.get('artist_id')
  const serviceId = searchParams.get('service_id')
  const status = searchParams.get('status')
  const page = Math.max(1, parseInt(searchParams.get('page') ?? '1', 10))
  const perPage = Math.min(100, Math.max(1, parseInt(searchParams.get('per_page') ?? '50', 10)))
  const offset = (page - 1) * perPage

  try {
    const supabase = await createClient()

    let query = supabase
      .from('waitlist_entries')
      .select(
        `
        id,
        status,
        created_at,
        offered_at,
        offered_expires_at,
        offered_booking_id,
        notes,
        preferred_dates,
        preferred_days_of_week,
        client:clients(id, first_name, last_name, email, phone),
        artist:artists(id, display_name, avatar_url),
        service:services(id, name, duration_min, color)
      `,
        { count: 'exact' },
      )
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: false })
      .range(offset, offset + perPage - 1)

    if (artistId) query = query.eq('artist_id', artistId)
    if (serviceId) query = query.eq('service_id', serviceId)
    if (status) query = query.eq('status', status)

    const { data, count, error } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'waitlist list fetch failed')
      return NextResponse.json({ error: 'Failed to fetch waitlist' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page: perPage,
      total_pages: Math.ceil((count ?? 0) / perPage),
    })
  } catch (err) {
    logger.error({ err }, 'waitlist list GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useRef, useEffect } from 'react'
import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { ChevronDown } from 'lucide-react'
import { cn } from '@/lib/utils'

export type WaitlistStatus = 'active' | 'offered' | 'expired' | 'cancelled' | 'booked'

interface FilterOption {
  id: string
  name: string
}

interface WaitlistFilterPillsProps {
  artists: FilterOption[]
  services: FilterOption[]
  events: FilterOption[]
  /** URL-driven current values */
  currentArtistId?: string
  currentServiceId?: string
  currentEventId?: string
  currentStatus?: WaitlistStatus
}

const STATUS_OPTIONS: { value: WaitlistStatus; label: string }[] = [
  { value: 'active', label: 'Active' },
  { value: 'offered', label: 'Offered' },
  { value: 'booked', label: 'Booked' },
  { value: 'expired', label: 'Expired' },
  { value: 'cancelled', label: 'Cancelled' },
]

/**
 * URL-driven filter pills for the Waitlist tab.
 * Selected state = Onyx bg + bone text. Unselected = outline.
 * Dropdowns are native-friendly popovers for accessibility.
 */
export function WaitlistFilterPills({
  artists,
  services,
  events,
  currentArtistId,
  currentServiceId,
  currentEventId,
  currentStatus,
}: WaitlistFilterPillsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  function setFilter(key: string, value: string | null) {
    const params = new URLSearchParams(searchParams.toString())
    if (value) {
      params.set(key, value)
      // Clear conflicting filters when switching pill type
      if (key === 'w_artist') { params.delete('w_service'); params.delete('w_event') }
      if (key === 'w_service') { params.delete('w_artist'); params.delete('w_event') }
      if (key === 'w_event') { params.delete('w_artist'); params.delete('w_service') }
    } else {
      params.delete(key)
    }
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  function clearAll() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('w_artist')
    params.delete('w_service')
    params.delete('w_event')
    params.delete('w_status')
    router.replace(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const isFiltered = !!(currentArtistId || currentServiceId || currentEventId || currentStatus)
  const isAllActive = !isFiltered

  return (
    <div
      className="flex flex-wrap items-center gap-2"
      role="group"
      aria-label="Waitlist filters"
    >
      {/* All */}
      <Pill
        label="All"
        active={isAllActive}
        onClick={clearAll}
        aria-label="Show all waitlist entries"
      />

      {/* Per artist */}
      <DropdownPill
        label="Artist"
        options={artists}
        selectedId={currentArtistId}
        onSelect={(id) => setFilter('w_artist', id)}
        onClear={() => setFilter('w_artist', null)}
        aria-label="Filter by artist"
      />

      {/* Per service */}
      <DropdownPill
        label="Service"
        options={services}
        selectedId={currentServiceId}
        onSelect={(id) => setFilter('w_service', id)}
        onClear={() => setFilter('w_service', null)}
        aria-label="Filter by service"
      />

      {/* Per flash event */}
      {events.length > 0 && (
        <DropdownPill
          label="Flash event"
          options={events}
          selectedId={currentEventId}
          onSelect={(id) => setFilter('w_event', id)}
          onClear={() => setFilter('w_event', null)}
          aria-label="Filter by flash event"
        />
      )}

      {/* By status */}
      <DropdownPill
        label="Status"
        options={STATUS_OPTIONS.map((s) => ({ id: s.value, name: s.label }))}
        selectedId={currentStatus}
        onSelect={(id) => setFilter('w_status', id)}
        onClear={() => setFilter('w_status', null)}
        aria-label="Filter by status"
      />
    </div>
  )
}

// ── Internal pill atom ────────────────────────────────────────────────────────

interface PillProps {
  label: string
  active: boolean
  onClick: () => void
  'aria-label'?: string
}

function Pill({ label, active, onClick, 'aria-label': ariaLabel }: PillProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={ariaLabel ?? label}
      aria-pressed={active}
      className={cn(
        'inline-flex h-7 items-center rounded-full border px-3 text-xs font-medium transition-colors',
        active
          ? 'border-[color:var(--color-onyx)] bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
          : 'border-[color:var(--color-border)] bg-transparent text-[color:var(--color-onyx)] hover:border-[color:var(--color-onyx)]',
      )}
    >
      {label}
    </button>
  )
}

// ── Dropdown pill ─────────────────────────────────────────────────────────────

interface DropdownPillProps {
  label: string
  options: FilterOption[]
  selectedId?: string
  onSelect: (id: string) => void
  onClear: () => void
  'aria-label'?: string
}

function DropdownPill({
  label,
  options,
  selectedId,
  onSelect,
  onClear,
  'aria-label': ariaLabel,
}: DropdownPillProps) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  const selectedOption = options.find((o) => o.id === selectedId)
  const isActive = !!selectedId

  // Close on outside click
  useEffect(() => {
    function onPointerDown(e: PointerEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    if (open) {
      document.addEventListener('pointerdown', onPointerDown)
      return () => document.removeEventListener('pointerdown', onPointerDown)
    }
  }, [open])

  // Close on Escape
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') setOpen(false)
    }
    if (open) {
      document.addEventListener('keydown', onKey)
      return () => document.removeEventListener('keydown', onKey)
    }
  }, [open])

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        aria-label={ariaLabel ?? label}
        aria-expanded={open}
        aria-haspopup="listbox"
        onClick={() => setOpen((o) => !o)}
        className={cn(
          'inline-flex h-7 items-center gap-1 rounded-full border px-3 text-xs font-medium transition-colors',
          isActive
            ? 'border-[color:var(--color-onyx)] bg-[color:var(--color-onyx)] text-[color:var(--color-bone)]'
            : 'border-[color:var(--color-border)] bg-transparent text-[color:var(--color-onyx)] hover:border-[color:var(--color-onyx)]',
        )}
      >
        {isActive ? selectedOption?.name ?? label : label}
        <ChevronDown
          className={cn('h-3 w-3 shrink-0 transition-transform', open && 'rotate-180')}
          aria-hidden
        />
      </button>

      {open && (
        <div
          role="listbox"
          aria-label={`${label} options`}
          className="absolute top-full z-20 mt-1 min-w-[10rem] rounded-lg border border-[color:var(--color-border)] bg-[color:var(--color-bone)] py-1 shadow-lift"
        >
          {isActive && (
            <button
              type="button"
              role="option"
              aria-selected={false}
              onClick={() => { onClear(); setOpen(false) }}
              className="w-full px-3 py-1.5 text-left text-xs text-[color:var(--color-stone)] hover:bg-[color:var(--color-border)]/20"
            >
              Clear filter
            </button>
          )}
          {options.map((opt) => (
            <button
              key={opt.id}
              type="button"
              role="option"
              aria-selected={opt.id === selectedId}
              onClick={() => { onSelect(opt.id); setOpen(false) }}
              className={cn(
                'w-full px-3 py-1.5 text-left text-xs transition-colors',
                opt.id === selectedId
                  ? 'font-medium text-[color:var(--color-onyx)]'
                  : 'text-[color:var(--color-onyx)] hover:bg-[color:var(--color-border)]/20',
              )}
            >
              {opt.name}
            </button>
          ))}
          {options.length === 0 && (
            <p className="px-3 py-2 text-xs text-[color:var(--color-stone)]">None available</p>
          )}
        </div>
      )}
    </div>
  )
}

'use client'

import { useRouter, usePathname, useSearchParams } from 'next/navigation'
import { Button } from '@/components/ui/button'
import { Mail } from 'lucide-react'
import type { WaitlistStatus } from './WaitlistFilterPills'

interface WaitlistFilter {
  artistId?: string
  serviceId?: string
  eventId?: string
  status?: WaitlistStatus
  /** Resolved client IDs from the filtered waitlist (passed in from WaitlistList) */
  clientIds?: string[]
}

interface MessageWaitlistButtonProps {
  filter: WaitlistFilter
  /** Count of entries in the filtered set (for accessibility label) */
  count: number
}

/**
 * Opens the campaign drawer with a transient audience filter representing
 * the current waitlist filter set.
 *
 * Encodes the filter as a base64 JSON payload in the URL:
 *   ?campaign=new&waitlist_filter=<base64>
 *
 * CampaignDrawer parses this and translates to a client_ids audience filter.
 */
export function MessageWaitlistButton({ filter, count }: MessageWaitlistButtonProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  function openDrawer() {
    const params = new URLSearchParams(searchParams.toString())
    params.set('campaign', 'new')

    // Encode filter as base64 JSON for the drawer to parse
    const encoded = btoa(JSON.stringify(filter))
    params.set('waitlist_filter', encoded)

    router.push(`${pathname}?${params.toString()}`, { scroll: false })
  }

  const label = count > 0
    ? `Message ${count.toLocaleString()} waitlist ${count === 1 ? 'member' : 'members'}`
    : 'Message the waitlist'

  return (
    <Button
      type="button"
      variant="default"
      size="sm"
      className="h-8 gap-1.5 text-xs"
      onClick={openDrawer}
      disabled={count === 0}
      aria-label={label}
    >
      <Mail className="h-3.5 w-3.5 shrink-0" aria-hidden />
      Message the list
    </Button>
  )
}

'use client'

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { MessageWaitlistButton } from './MessageWaitlistButton'
import { formatDate } from '@/lib/utils'
import { cn } from '@/lib/utils'
import { Clock, ChevronLeft, ChevronRight } from 'lucide-react'
import type { WaitlistStatus } from './WaitlistFilterPills'

interface WaitlistEntry {
  id: string
  status: string
  created_at: string
  offered_at: string | null
  offered_expires_at: string | null
  notes: string | null
  client: {
    id: string
    first_name: string
    last_name: string | null
    email: string | null
  } | null
  artist: { id: string; display_name: string } | null
  service: { id: string; name: string; color: string | null } | null
}

interface WaitlistListResponse {
  data: WaitlistEntry[]
  count: number
  page: number
  per_page: number
  total_pages: number
}

interface WaitlistListProps {
  artistId?: string
  serviceId?: string
  eventId?: string
  status?: WaitlistStatus
}

const STATUS_CLASSES: Record<string, string> = {
  active: 'bg-[color:var(--color-bone)] border border-[color:var(--color-border)] text-[color:var(--color-onyx)]',
  offered: 'border border-amber-300 bg-amber-50 text-amber-800',
  booked: 'border border-green-300 bg-green-50 text-green-800',
  expired: 'bg-[color:var(--color-bone)] text-[color:var(--color-stone)]',
  cancelled: 'bg-[color:var(--color-bone)] text-[color:var(--color-stone)]',
}

const PER_PAGE = 50

/**
 * Client component — fetches filtered waitlist entries and renders the table.
 * Reuses table primitives from the waitlist CRUD module; adapts for marketing context.
 */
export function WaitlistList({ artistId, serviceId, eventId, status }: WaitlistListProps) {
  const [page, setPage] = useState(1)

  const queryKey = ['marketing-waitlist', 'list', { artistId, serviceId, eventId, status, page }]

  const { data, isLoading, error } = useQuery<WaitlistListResponse>({
    queryKey,
    queryFn: async () => {
      const params = new URLSearchParams({ per_page: String(PER_PAGE), page: String(page) })
      if (artistId) params.set('artist_id', artistId)
      if (serviceId) params.set('service_id', serviceId)
      if (eventId) params.set('event_id', eventId)
      if (status) params.set('status', status)
      const res = await fetch(`/api/marketing/waitlist/list?${params.toString()}`)
      if (!res.ok) throw new Error('Failed to fetch waitlist')
      return res.json() as Promise<WaitlistListResponse>
    },
  })

  // Reset page when filters change
  const totalPages = data?.total_pages ?? 1
  const totalCount = data?.count ?? 0

  const clientIds = (data?.data ?? [])
    .map((e) => e.client?.id)
    .filter((id): id is string => typeof id === 'string')

  const currentFilter = { artistId, serviceId, eventId, status, clientIds }

  return (
    <div className="flex flex-col gap-3">
      {/* Toolbar */}
      <div className="flex items-center justify-between">
        <p className="text-xs text-[color:var(--color-stone)] tabular-nums">
          {totalCount.toLocaleString()} {totalCount === 1 ? 'entry' : 'entries'}
        </p>
        <MessageWaitlistButton filter={currentFilter} count={totalCount} />
      </div>

      {/* Table */}
      <div className="overflow-hidden rounded-lg border border-[color:var(--color-border)] shadow-card">
        <DataState
          data={data?.data}
          isLoading={isLoading}
          isError={!!error}
          error={error instanceof Error ? error : null}
          loadingSlot={<TableSkeleton rows={6} />}
          emptySlot={
            <EmptyState
              icon={Clock}
              title="No waitlist entries"
              description={
                artistId || serviceId || eventId || status
                  ? 'No entries match the current filters. Try adjusting above.'
                  : 'No one on the waitlist yet — clients can join from your booking page.'
              }
              variant={artistId || serviceId || eventId || status ? 'no-results' : 'default'}
            />
          }
        >
          {(entries) => (
            <>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Client</TableHead>
                    <TableHead>Service</TableHead>
                    <TableHead>Artist</TableHead>
                    <TableHead>Joined</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {entries.map((entry) => (
                    <TableRow key={entry.id}>
                      <TableCell>
                        {entry.client ? (
                          <div>
                            <p className="text-sm font-medium text-[color:var(--color-onyx)]">
                              {entry.client.first_name} {entry.client.last_name ?? ''}
                            </p>
                            {entry.client.email && (
                              <p className="text-xs text-[color:var(--color-stone)] truncate max-w-[160px]">
                                {entry.client.email}
                              </p>
                            )}
                          </div>
                        ) : (
                          <span className="text-xs text-[color:var(--color-stone)]">—</span>
                        )}
                      </TableCell>

                      <TableCell>
                        {entry.service ? (
                          <div className="flex items-center gap-1.5">
                            {entry.service.color && (
                              <span
                                className="h-2 w-2 shrink-0 rounded-full"
                                style={{ backgroundColor: entry.service.color }}
                                aria-hidden
                              />
                            )}
                            <span className="text-sm truncate max-w-[120px]">
                              {entry.service.name}
                            </span>
                          </div>
                        ) : (
                          <span className="text-xs text-[color:var(--color-stone)]">Any</span>
                        )}
                      </TableCell>

                      <TableCell>
                        <span className="text-sm">
                          {entry.artist?.display_name ?? (
                            <span className="text-xs text-[color:var(--color-stone)]">Any</span>
                          )}
                        </span>
                      </TableCell>

                      <TableCell className="text-xs text-[color:var(--color-stone)] tabular-nums">
                        {formatDate(entry.created_at, { month: 'short', day: 'numeric' })}
                      </TableCell>

                      <TableCell>
                        <span
                          className={cn(
                            'inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium capitalize',
                            STATUS_CLASSES[entry.status] ?? STATUS_CLASSES.expired,
                          )}
                        >
                          {entry.status}
                        </span>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-between border-t border-[color:var(--color-border)] px-4 py-3">
                  <p className="text-xs text-[color:var(--color-stone)] tabular-nums">
                    {(page - 1) * PER_PAGE + 1}–{Math.min(page * PER_PAGE, totalCount)} of{' '}
                    {totalCount}
                  </p>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7"
                      disabled={page === 1}
                      onClick={() => setPage((p) => p - 1)}
                      aria-label="Previous page"
                    >
                      <ChevronLeft className="h-4 w-4" aria-hidden />
                    </Button>
                    <span className="px-2 text-xs tabular-nums">
                      {page} / {totalPages}
                    </span>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-7 w-7"
                      disabled={page === totalPages}
                      onClick={() => setPage((p) => p + 1)}
                      aria-label="Next page"
                    >
                      <ChevronRight className="h-4 w-4" aria-hidden />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </DataState>
      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  CardDescription,
} from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Switch } from '@/components/ui/switch'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { logger } from '@/lib/logger'

interface AutoPromoteRules {
  auto_promote_on_cancel: boolean
  auto_promote_window_minutes: number
  min_lead_time_hours: number
  notify_via: string[]
  template_subject: string
  template_body: string
}

interface AutoPromoteRulesCardProps {
  initialRules: AutoPromoteRules
}

const FormSchema = z.object({
  auto_promote_on_cancel: z.boolean(),
  auto_promote_window_minutes: z.coerce.number().int().min(0).max(1440),
  min_lead_time_hours: z.coerce.number().int().min(0).max(168),
  notify_via_email: z.boolean(),
  template_subject: z.string().min(1, 'Subject is required').max(200),
  template_body: z.string().min(1, 'Message body is required').max(2000),
})

type FormValues = z.infer<typeof FormSchema>

/**
 * Inline auto-promote rules card on the Marketing > Waitlist tab.
 * Settings are saved via PATCH /api/marketing/waitlist/auto-promote-rules.
 * SMS channel hidden until Twilio is wired (M6+).
 */
export function AutoPromoteRulesCard({ initialRules }: AutoPromoteRulesCardProps) {
  const [isSaving, setIsSaving] = useState(false)

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors, isDirty },
  } = useForm<FormValues>({
    resolver: zodResolver(FormSchema),
    defaultValues: {
      auto_promote_on_cancel: initialRules.auto_promote_on_cancel,
      auto_promote_window_minutes: initialRules.auto_promote_window_minutes,
      min_lead_time_hours: initialRules.min_lead_time_hours,
      notify_via_email: initialRules.notify_via.includes('email'),
      template_subject: initialRules.template_subject,
      template_body: initialRules.template_body,
    },
  })

  const isEnabled = watch('auto_promote_on_cancel')

  async function onSubmit(values: FormValues) {
    setIsSaving(true)
    try {
      const notify_via: string[] = []
      if (values.notify_via_email) notify_via.push('email')
      if (notify_via.length === 0) notify_via.push('email') // default fallback

      const res = await fetch('/api/marketing/waitlist/auto-promote-rules', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          auto_promote_on_cancel: values.auto_promote_on_cancel,
          auto_promote_window_minutes: values.auto_promote_window_minutes,
          min_lead_time_hours: values.min_lead_time_hours,
          notify_via,
          template_subject: values.template_subject,
          template_body: values.template_body,
        }),
      })

      if (!res.ok) {
        const err = await res.json() as { error?: string }
        throw new Error(err.error ?? 'Failed to save rules')
      }

      toast.success('Auto-promote rules saved')
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Failed to save rules'
      toast.error(msg)
      logger.error({ err }, 'auto-promote rules save failed')
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <Card className="border-[color:var(--color-border)] bg-[color:var(--color-bone)] shadow-card">
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between gap-4">
          <div>
            <CardTitle className="text-base font-semibold text-[color:var(--color-onyx)]">
              Auto-promote on cancellation
            </CardTitle>
            <CardDescription className="mt-0.5 text-sm text-[color:var(--color-stone)]">
              When a booking is cancelled with enough lead time, InkOS automatically notifies
              the next eligible waitlist member.
            </CardDescription>
          </div>
          {/* Master toggle */}
          <Switch
            id="auto-promote-toggle"
            checked={isEnabled}
            onCheckedChange={(checked) => setValue('auto_promote_on_cancel', checked, { shouldDirty: true })}
            aria-label="Enable auto-promote on cancellation"
          />
        </div>
      </CardHeader>

      <CardContent>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
          {/* Window + lead time — only meaningful when enabled */}
          <div
            className={`grid grid-cols-1 gap-4 transition-opacity sm:grid-cols-2 ${
              isEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none select-none'
            }`}
          >
            {/* Window */}
            <div className="space-y-1.5">
              <Label
                htmlFor="window-minutes"
                className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]"
              >
                Notify within (minutes after cancel)
              </Label>
              <input
                id="window-minutes"
                type="number"
                min={0}
                max={1440}
                {...register('auto_promote_window_minutes')}
                className="h-9 w-full rounded-md border border-[color:var(--color-border)] bg-[color:var(--color-bone)] px-3 text-sm tabular-nums text-[color:var(--color-onyx)] focus:outline-none focus:ring-2 focus:ring-[color:var(--color-onyx)]/30"
                aria-describedby="window-hint"
              />
              <p id="window-hint" className="text-xs text-[color:var(--color-stone)]">
                0 = notify immediately on cancel
              </p>
              {errors.auto_promote_window_minutes && (
                <p className="text-xs text-[color:var(--color-rust)]">
                  {errors.auto_promote_window_minutes.message}
                </p>
              )}
            </div>

            {/* Min lead time */}
            <div className="space-y-1.5">
              <Label
                htmlFor="lead-time"
                className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]"
              >
                Only if cancellation ≥ (hours before slot)
              </Label>
              <input
                id="lead-time"
                type="number"
                min={0}
                max={168}
                {...register('min_lead_time_hours')}
                className="h-9 w-full rounded-md border border-[color:var(--color-border)] bg-[color:var(--color-bone)] px-3 text-sm tabular-nums text-[color:var(--color-onyx)] focus:outline-none focus:ring-2 focus:ring-[color:var(--color-onyx)]/30"
              />
              {errors.min_lead_time_hours && (
                <p className="text-xs text-[color:var(--color-rust)]">
                  {errors.min_lead_time_hours.message}
                </p>
              )}
            </div>
          </div>

          {/* Channel checkboxes */}
          <div
            className={`space-y-2 transition-opacity ${
              isEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none select-none'
            }`}
          >
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
              Notify via
            </p>
            <div className="flex flex-wrap gap-4">
              <label className="flex items-center gap-2 text-sm text-[color:var(--color-onyx)]">
                <input
                  type="checkbox"
                  {...register('notify_via_email')}
                  className="h-4 w-4 rounded border-[color:var(--color-border)] accent-[color:var(--color-onyx)]"
                />
                Email
              </label>
              {/* SMS hidden until M6+ Twilio */}
              <label className="flex cursor-not-allowed items-center gap-2 text-sm text-[color:var(--color-stone)] opacity-50">
                <input type="checkbox" disabled className="h-4 w-4 rounded border-[color:var(--color-border)]" />
                SMS <span className="text-[10px]">(coming soon)</span>
              </label>
            </div>
          </div>

          {/* Template */}
          <div
            className={`space-y-3 transition-opacity ${
              isEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none select-none'
            }`}
          >
            <p className="text-[11px] font-bold uppercase tracking-[0.08em] text-[color:var(--color-stone)]">
              Message template
            </p>

            <div className="space-y-1.5">
              <Label htmlFor="template-subject" className="sr-only">
                Subject
              </Label>
              <input
                id="template-subject"
                type="text"
                placeholder="Subject line"
                {...register('template_subject')}
                className="h-9 w-full rounded-md border border-[color:var(--color-border)] bg-[color:var(--color-bone)] px-3 text-sm text-[color:var(--color-onyx)] focus:outline-none focus:ring-2 focus:ring-[color:var(--color-onyx)]/30"
                aria-label="Template subject line"
              />
              {errors.template_subject && (
                <p className="text-xs text-[color:var(--color-rust)]">
                  {errors.template_subject.message}
                </p>
              )}
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="template-body" className="sr-only">
                Message body
              </Label>
              <Textarea
                id="template-body"
                rows={3}
                placeholder="A slot just opened: {{slot}}. Reply YES to claim it."
                {...register('template_body')}
                className="resize-none text-sm text-[color:var(--color-onyx)]"
                aria-label="Template message body"
                aria-describedby="merge-tag-hint"
              />
              <p id="merge-tag-hint" className="text-xs text-[color:var(--color-stone)]">
                Use <code className="rounded bg-[color:var(--color-border)]/40 px-1">{'{{slot}}'}</code>{' '}
                for the booking date, time, and artist.
              </p>
              {errors.template_body && (
                <p className="text-xs text-[color:var(--color-rust)]">
                  {errors.template_body.message}
                </p>
              )}
            </div>
          </div>

          {/* Save button */}
          <div className="flex justify-end">
            <Button
              type="submit"
              size="sm"
              className="h-8 text-xs"
              disabled={isSaving || !isDirty}
              aria-label="Save auto-promote rules"
            >
              {isSaving ? 'Saving…' : 'Save rules'}
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  )
}

import { Suspense } from 'react'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio } from '@/lib/context/active-studio'
import { WaitlistMetricsRow } from './WaitlistMetricsRow'
import { WaitlistFilterPills } from './WaitlistFilterPills'
import { WaitlistList } from './WaitlistList'
import { AutoPromoteRulesCard } from './AutoPromoteRulesCard'
import type { WaitlistStatus } from './WaitlistFilterPills'

interface FilterOption {
  id: string
  name: string
}

interface AutoPromoteRules {
  auto_promote_on_cancel: boolean
  auto_promote_window_minutes: number
  min_lead_time_hours: number
  notify_via: string[]
  template_subject: string
  template_body: string
}

const DEFAULT_RULES: AutoPromoteRules = {
  auto_promote_on_cancel: false,
  auto_promote_window_minutes: 5,
  min_lead_time_hours: 24,
  notify_via: ['email'],
  template_subject: 'A spot just opened',
  template_body: 'A slot just opened: {{slot}}. Reply YES to claim it — this offer expires in 24 hours.',
}

interface WaitlistTabProps {
  /** URL-driven filter params from marketing/page.tsx */
  artistId?: string
  serviceId?: string
  eventId?: string
  status?: WaitlistStatus
}

/**
 * Marketing > Waitlist tab — server component.
 *
 * Fetches:
 * - Conversion stats (30d joined / converted / rate / delta)
 * - marketing_waitlist_rules for the studio (auto-promote settings)
 * - Artists, services, flash_events for filter pills
 *
 * The WaitlistList itself is a client component that fetches entries
 * filtered by URL params.
 */
export async function WaitlistTab({ artistId, serviceId, eventId, status }: WaitlistTabProps) {
  const { studioId } = await getActiveStudio()
  const supabase = await createClient()

  // Parallel fetches — all are non-blocking for the page shell
  const [conversionRes, rulesRes, artistsRes, servicesRes, eventsRes] = await Promise.all([
    // Conversion stats via API route to keep logic in one place
    fetch(
      new URL(
        `/api/marketing/waitlist/conversion`,
        process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000',
      ).toString(),
      { cache: 'no-store' },
    ).then((r) => r.ok ? r.json() as Promise<{ data: ConversionData }> : null).catch(() => null),

    // Auto-promote rules
    supabase
      .from('marketing_waitlist_rules')
      .select('*')
      .eq('studio_id', studioId)
      .maybeSingle(),

    // Artists for filter pills
    supabase
      .from('artists')
      .select('id, display_name')
      .eq('studio_id', studioId)
      .eq('status', 'active')
      .order('display_name'),

    // Services for filter pills
    supabase
      .from('services')
      .select('id, name')
      .eq('studio_id', studioId)
      .eq('is_active', true)
      .order('name'),

    // Flash events for filter pills (upcoming/active only)
    supabase
      .from('flash_events')
      .select('id, title')
      .eq('studio_id', studioId)
      .in('status', ['draft', 'published'])
      .order('event_date', { ascending: false })
      .limit(20),
  ])

  const conversionData: ConversionData = (conversionRes as { data: ConversionData } | null)?.data ?? {
    joined_30d: 0,
    converted_30d: 0,
    conversion_rate: 0,
    prior_period_rate: 0,
    delta_pct: null,
  }

  const rules: AutoPromoteRules = (rulesRes.data as AutoPromoteRules | null) ?? DEFAULT_RULES

  const artists: FilterOption[] = (artistsRes.data ?? []).map((a) => ({
    id: a.id,
    name: a.display_name,
  }))

  const services: FilterOption[] = (servicesRes.data ?? []).map((s) => ({
    id: s.id,
    name: s.name,
  }))

  const events: FilterOption[] = (eventsRes.data ?? []).map((e) => ({
    id: e.id,
    name: e.title,
  }))

  return (
    <div className="space-y-5">
      {/* Conversion metrics strip */}
      <Suspense fallback={<MetricsRowSkeleton />}>
        <WaitlistMetricsRow metrics={conversionData} />
      </Suspense>

      {/* Filter pills */}
      <WaitlistFilterPills
        artists={artists}
        services={services}
        events={events}
        currentArtistId={artistId}
        currentServiceId={serviceId}
        currentEventId={eventId}
        currentStatus={status}
      />

      {/* Waitlist entries */}
      <WaitlistList
        artistId={artistId}
        serviceId={serviceId}
        eventId={eventId}
        status={status}
      />

      {/* Auto-promote rules card */}
      <AutoPromoteRulesCard initialRules={rules} />
    </div>
  )
}

function MetricsRowSkeleton() {
  return (
    <div className="h-11 animate-pulse rounded-lg border border-[color:var(--color-border)] bg-[color:var(--color-border)]/30" />
  )
}

