// ── Waitlist filter parsing ────────────────────────────────────────────────────

interface WaitlistFilterPayload {
  artistId?: string
  serviceId?: string
  eventId?: string
  status?: string
  clientIds?: string[]
}

function parseWaitlistFilter(encoded: string | null): { filter: AudienceFilter; count: number } | null {
  if (!encoded) return null
  try {
    const decoded = atob(encoded)
    const payload = JSON.parse(decoded) as WaitlistFilterPayload
    const clientIds = Array.isArray(payload.clientIds) ? payload.clientIds.filter((id): id is string => typeof id === 'string') : []
    if (clientIds.length === 0) return null
    // Use a flat filter shape that the audience count RPC can understand
    // client_ids_in is not yet supported by the RPC — count comes from clientIds.length directly
    return { filter: {}, count: clientIds.length }
  } catch {
    return null
  }
}

