input.content:
/**
 * marketing-waitlist-auto-promote — pg_notify listener worker.
 *
 * The M6 booking-cancel trigger fires:
 *   pg_notify('waitlist_auto_promote', booking_id::text)
 *
 * This worker LISTENs on that channel and processes the auto-promote flow:
 *  1. Parse booking_id from the notification payload.
 *  2. Load the booking → identify slot (artist_id, service_id, start_at, studio_id).
 *  3. Load marketing_waitlist_rules for that studio. If disabled → skip.
 *  4. Check min_lead_time_hours: if cancellation < lead-time before slot → skip.
 *  5. Find the first active waitlist_entry matching (studio, artist or service).
 *  6. Delay auto_promote_window_minutes via a BullMQ delayed job.
 *  7. The send-waitlist-offer job (enqueued below) sends via Resend, respects
 *     client_consent_preferences.marketing_email, respects email_suppression_list.
 *  8. Updates waitlist_entry to status='offered', offered_at=now, offered_expires_at=now+24h.
 *
 * NOTE: The actual Resend send is stubbed as a TODO below. The LISTEN/decode/gate/enqueue
 * logic is fully implemented. Wire the Resend send when email templates are finalized (M6+).
 *
 * Worker package: workers/ (separate Railway service, never imports from next/*)
 * Start command: pnpm -C workers jobs
 */

import { Client } from 'pg'
import { workerEnv } from '../lib/env.js'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { enqueueJob } from '../lib/queue.js'

const CHANNEL = 'waitlist_auto_promote'

// ── Types ─────────────────────────────────────────────────────────────────────

interface WaitlistRulesRow {
  auto_promote_on_cancel: boolean
  auto_promote_window_minutes: number
  min_lead_time_hours: number
  notify_via: string[]
  template_subject: string
  template_body: string
}

interface BookingRow {
  id: string
  studio_id: string
  artist_id: string | null
  service_id: string | null
  start_at: string
  status: string
  cancelled_at: string | null
}

interface WaitlistEntryRow {
  id: string
  client_id: string
  studio_id: string
  artist_id: string | null
  service_id: string | null
  status: string
}

interface ConsentRow {
  marketing_email: boolean | null
}

// ── Listener ──────────────────────────────────────────────────────────────────

export async function startWaitlistAutoPromoteListener(): Promise<void> {
  const pgClient = new Client({ connectionString: workerEnv.NEXT_PUBLIC_SUPABASE_URL })
  await pgClient.connect()

  logger.info({ channel: CHANNEL }, 'marketing-waitlist-auto-promote: listening')

  await pgClient.query(`LISTEN "${CHANNEL}"`)

  pgClient.on('notification', (msg) => {
    if (msg.channel !== CHANNEL) return
    const bookingId = msg.payload?.trim()
    if (!bookingId) {
      logger.warn('marketing-waitlist-auto-promote: received empty payload, skipping')
      return
    }
    void processAutoPromote(bookingId).catch((err: unknown) => {
      logger.error({ err, bookingId }, 'marketing-waitlist-auto-promote: unhandled error')
    })
  })

  pgClient.on('error', (err) => {
    logger.error({ err }, 'marketing-waitlist-auto-promote: pg client error')
  })
}

// ── Core processing ───────────────────────────────────────────────────────────

async function processAutoPromote(bookingId: string): Promise<void> {
  logger.info({ bookingId }, 'marketing-waitlist-auto-promote: processing')

  // 1. Load booking
  const { data: booking, error: bookingErr } = await supabase
    .from('bookings')
    .select('id, studio_id, artist_id, service_id, start_at, status, cancelled_at')
    .eq('id', bookingId)
    .single()

  if (bookingErr || !booking) {
    logger.warn({ bookingId, err: bookingErr }, 'marketing-waitlist-auto-promote: booking not found')
    return
  }

  const b = booking as BookingRow

  if (b.status !== 'cancelled') {
    logger.info({ bookingId }, 'marketing-waitlist-auto-promote: booking not cancelled, skipping')
    return
  }

  // 2. Load studio auto-promote rules
  const { data: rules, error: rulesErr } = await supabase
    .from('marketing_waitlist_rules')
    .select('*')
    .eq('studio_id', b.studio_id)
    .maybeSingle()

  if (rulesErr) {
    logger.error({ err: rulesErr, studioId: b.studio_id }, 'marketing-waitlist-auto-promote: rules fetch failed')
    return
  }

  if (!rules) {
    logger.info({ studioId: b.studio_id }, 'marketing-waitlist-auto-promote: no rules configured, skipping')
    return
  }

  const r = rules as WaitlistRulesRow

  if (!r.auto_promote_on_cancel) {
    logger.info({ studioId: b.studio_id }, 'marketing-waitlist-auto-promote: auto-promote disabled, skipping')
    return
  }

  // 3. Check min_lead_time_hours
  const slotAt = new Date(b.start_at).getTime()
  const now = Date.now()
  const leadTimeMs = r.min_lead_time_hours * 60 * 60 * 1000

  if (slotAt - now < leadTimeMs) {
    logger.info(
      { bookingId, leadTimeHours: r.min_lead_time_hours },
      'marketing-waitlist-auto-promote: insufficient lead time, skipping',
    )
    return
  }

  // 4. Find first active waitlist entry matching studio + (artist or service)
  let waitlistQuery = supabase
    .from('waitlist_entries')
    .select('id, client_id, studio_id, artist_id, service_id, status')
    .eq('studio_id', b.studio_id)
    .eq('status', 'active')
    .order('created_at', { ascending: true })
    .limit(1)

  // Prefer matching on artist_id if available, fall back to service_id
  if (b.artist_id) {
    waitlistQuery = waitlistQuery.eq('artist_id', b.artist_id)
  } else if (b.service_id) {
    waitlistQuery = waitlistQuery.eq('service_id', b.service_id)
  }

  const { data: entries, error: entriesErr } = await waitlistQuery

  if (entriesErr) {
    logger.error({ err: entriesErr }, 'marketing-waitlist-auto-promote: waitlist query failed')
    return
  }

  if (!entries || entries.length === 0) {
    logger.info({ bookingId }, 'marketing-waitlist-auto-promote: no matching waitlist entries, skipping')
    return
  }

  const entry = entries[0] as WaitlistEntryRow

  // 5. Check client consent (respect marketing_email preference)
  const { data: consent } = await supabase
    .from('client_consent_preferences')
    .select('marketing_email')
    .eq('client_id', entry.client_id)
    .maybeSingle()

  const consentRow = consent as ConsentRow | null

  // marketing_email defaults to true if not set — only skip if explicitly false
  if (consentRow && consentRow.marketing_email === false) {
    logger.info(
      { clientId: entry.client_id },
      'marketing-waitlist-auto-promote: client opted out of marketing email, skipping',
    )
    return
  }

  // 6. Check email suppression list
  const { data: client } = await supabase
    .from('clients')
    .select('email')
    .eq('id', entry.client_id)
    .single()

  const clientEmail = (client as { email: string | null } | null)?.email

  if (clientEmail) {
    const { data: suppression } = await supabase
      .from('email_suppression_list')
      .select('email')
      .eq('studio_id', b.studio_id)
      .eq('email', clientEmail)
      .maybeSingle()

    if (suppression) {
      logger.info(
        { clientId: entry.client_id, email: clientEmail },
        'marketing-waitlist-auto-promote: client email suppressed, skipping',
      )
      return
    }
  }

  // 7. Enqueue the send with delay (auto_promote_window_minutes)
  const delayMs = r.auto_promote_window_minutes * 60 * 1000

  // Build slot description for template merge tag
  const slotDate = new Date(b.start_at).toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
  const templateBody = r.template_body.replace('{{slot}}', slotDate)
  const templateSubject = r.template_subject

  // TODO (M6+): Replace this enqueue stub with a dedicated 'send-waitlist-offer' job type
  // that handles Resend send + marketing_sends row insertion + entry status update.
  // For now: enqueue a generic send-email job as a best-effort stub.
  // The entry status update is done immediately below (optimistic) so the entry
  // doesn't get double-claimed if another event fires before the delay expires.

  if (clientEmail) {
    await enqueueJob(
      'send-email',
      {
        to: clientEmail,
        template: 'waitlist-auto-promote',
        data: {
          subject: templateSubject,
          body: templateBody,
          waitlist_entry_id: entry.id,
          booking_id: bookingId,
          studio_id: b.studio_id,
        },
      },
      { delay: delayMs },
    )

    logger.info(
      { entryId: entry.id, clientId: entry.client_id, delayMs },
      'marketing-waitlist-auto-promote: send-email job enqueued',
    )
  }

  // 8. Mark entry as offered
  const offeredAt = new Date()
  const offeredExpiresAt = new Date(offeredAt.getTime() + 24 * 60 * 60 * 1000)

  const { error: updateErr } = await supabase
    .from('waitlist_entries')
    .update({
      status: 'offered',
      offered_at: offeredAt.toISOString(),
      offered_expires_at: offeredExpiresAt.toISOString(),
      updated_at: offeredAt.toISOString(),
    })
    .eq('id', entry.id)

  if (updateErr) {
    logger.error(
      { err: updateErr, entryId: entry.id },
      'marketing-waitlist-auto-promote: failed to mark entry as offered',
    )
    return
  }

  logger.info(
    { entryId: entry.id, clientId: entry.client_id },
    'marketing-waitlist-auto-promote: entry marked as offered',
  )
}

